// LZ78 (Lempel & Ziv, 1978). The interview framing was not recovered; the algorithm is standard.
// A token is (Index, Next): Index of the longest dictionary phrase that prefixes the remaining
// input (0 = empty phrase), then the next character. If the input ends exactly on a known
// phrase, the last token's Next is '\0'.
public static class Lz78 {
    public static List<(int Index, char Next)> Encode(string s, int maxEntries = int.MaxValue) {
        var tokens = new List<(int, char)>();
        if (string.IsNullOrEmpty(s)) return tokens;
        if (maxEntries < 1) throw new ArgumentOutOfRangeException(nameof(maxEntries));
        var dict = new Dictionary<string, int>();
        int i = 0;
        while (i < s.Length) {
            int index = 0, len = 0;
            while (i + len < s.Length && dict.TryGetValue(s.Substring(i, len + 1), out var idx)) { index = idx; len++; }
            if (i + len == s.Length) { tokens.Add((index, '\0')); break; }
            char next = s[i + len];
            tokens.Add((index, next));
            if (dict.Count == maxEntries) dict.Clear();          // bounded memory: reset when full
            dict[s.Substring(i, len + 1)] = dict.Count + 1;
            i += len + 1;
        }
        return tokens;
    }

    public static string Decode(IList<(int Index, char Next)> tokens, int maxEntries = int.MaxValue) {
        var sb = new System.Text.StringBuilder();
        var phrases = new List<string> { "" };
        foreach (var (index, next) in tokens) {
            if (index < 0 || index >= phrases.Count) throw new FormatException($"token refers to phrase {index}, dictionary has {phrases.Count - 1}");
            string prefix = phrases[index];
            if (next == '\0') { sb.Append(prefix); break; }
            string phrase = prefix + next;
            sb.Append(phrase);
            if (phrases.Count - 1 == maxEntries) { phrases.Clear(); phrases.Add(""); }
            phrases.Add(phrase);
        }
        return sb.ToString();
    }
}
